import { TelemetryPolicyMismatchError } from '../../config/telemetryPolicy';
import fs from 'fs';
import path from 'path';
import type { ParsedFlags } from '../flags';
import { parseFlags, stringFlag, type FlagSpec } from '../flags';
import {
  errorResult,
  type CliCommandResult,
  type CliErrorRecovery,
} from '../envelope';
import type { CliErrorCode } from '../envelope';
import {
  inspectServer,
  type AttachedServer,
  type ServerAttachFailureReason,
} from '../client';
import { isServerStartInProgress } from '../serverHandshake';
import { parseHandoff, type CallerHandoff } from '../handoff';
import { errorMessage } from '../../utils/errorMessage';
import { PluginContextMismatchError } from '../../hosts/pluginContext';

export const commandErrorResult = (
  command: string,
  error: unknown,
): CliCommandResult =>
  error instanceof PluginContextMismatchError ||
  error instanceof TelemetryPolicyMismatchError
    ? errorResult(
        command,
        'SERVER_UNAVAILABLE',
        error.message,
        { serverUnavailableReason: error.reason },
        { isRecoverable: false },
      )
    : {
        ...errorResult(command, 'OPERATION_FAILED', errorMessage(error)),
        cause: error,
      };

export const SHARED_FLAG_SPEC: FlagSpec = {
  project: { takesValue: true },
  json: { takesValue: false },
  'no-telemetry': { takesValue: false },
  'caller-agent': { takesValue: true },
  'caller-model': { takesValue: true },
  'caller-session': { takesValue: true },
  handoff: { takesValue: true },
};

export const withSharedFlags = (spec: FlagSpec): FlagSpec => ({
  ...SHARED_FLAG_SPEC,
  ...spec,
});

export type CommandContext = {
  flags: ParsedFlags;
  projectPath: string;
  handoff: CallerHandoff | null;
};

export type AttachUnavailableReason =
  ServerAttachFailureReason | 'server_starting';

export type ServerAvailability =
  | { status: 'attached'; server: AttachedServer }
  | { status: 'unavailable'; reason: AttachUnavailableReason };

type ServerUnavailableResultOptions = {
  command: string;
  projectPath: string;
  reason: AttachUnavailableReason;
};

const ATTACH_RETRY_DELAYS_MS = [100, 250, 500] as const;
const RETRY_ACTION_DELAY_MS = 1_000;
const RETRY_SERVER_RECOVERY: CliErrorRecovery = {
  isRecoverable: true,
  nextAction: { action: 'retry', delayMs: RETRY_ACTION_DELAY_MS },
};

const sleep = (delayMs: number): Promise<void> =>
  new Promise((resolve) => setTimeout(resolve, delayMs));

export const parseCommandContext = (
  command: string,
  args: string[],
  spec: FlagSpec = {},
  env: NodeJS.ProcessEnv = process.env,
): CommandContext | CliCommandResult => {
  const flags = parseFlags(args, withSharedFlags(spec));
  if (flags.errors.length > 0) {
    return errorResult(command, 'USAGE_ERROR', flags.errors.join('; '));
  }

  const resolvedProjectPath = path.resolve(
    stringFlag(flags, 'project') ?? process.cwd(),
  );
  if (
    !fs.existsSync(resolvedProjectPath) ||
    !fs.statSync(resolvedProjectPath).isDirectory()
  ) {
    return errorResult(
      command,
      'USAGE_ERROR',
      `Project path is not a directory: ${resolvedProjectPath}`,
    );
  }
  const projectPath = fs.realpathSync.native(resolvedProjectPath);

  const handoffResult = parseHandoff(
    {
      callerAgent: stringFlag(flags, 'caller-agent'),
      callerModel: stringFlag(flags, 'caller-model'),
      callerSession: stringFlag(flags, 'caller-session'),
      handoffJson: stringFlag(flags, 'handoff'),
    },
    env,
  );
  if (!handoffResult.ok) {
    return errorResult(command, 'USAGE_ERROR', handoffResult.error);
  }

  return { flags, projectPath, handoff: handoffResult.handoff };
};

export const isCommandResult = (
  value: CommandContext | CliCommandResult,
): value is CliCommandResult => 'envelope' in value;

const isStartupAvailabilityReason = (
  reason: ServerAttachFailureReason,
): boolean =>
  reason === 'handshake_missing' ||
  reason === 'handshake_invalid' ||
  reason === 'process_not_running';

export const inspectServerAvailability = async (
  projectPath: string,
): Promise<ServerAvailability> => {
  let result = await inspectServer(projectPath);
  let hasRetriedHealthCheck = false;
  for (const retryDelayMs of ATTACH_RETRY_DELAYS_MS) {
    if (result.status === 'attached') {
      return result;
    }
    const isHealthRace =
      result.reason === 'health_check_failed' && !hasRetriedHealthCheck;
    const isStartupRace =
      (await isServerStartInProgress(projectPath)) &&
      isStartupAvailabilityReason(result.reason);
    if (!isHealthRace && !isStartupRace) {
      break;
    }
    hasRetriedHealthCheck =
      hasRetriedHealthCheck || result.reason === 'health_check_failed';
    await sleep(retryDelayMs);
    result = await inspectServer(projectPath);
  }
  if (result.status === 'attached') {
    return result;
  }
  if (
    (await isServerStartInProgress(projectPath)) &&
    isStartupAvailabilityReason(result.reason)
  ) {
    return { status: 'unavailable', reason: 'server_starting' };
  }
  return result;
};

export const serverUnavailableResult = (
  options: ServerUnavailableResultOptions,
): CliCommandResult => {
  const { command, projectPath, reason } = options;
  const openRecovery: CliErrorRecovery = {
    isRecoverable: true,
    nextAction: {
      action: 'open_project',
      command: 'rivet open',
      args: ['--project', projectPath],
    },
  };
  const recovery =
    reason === 'health_check_failed' || reason === 'server_starting'
      ? RETRY_SERVER_RECOVERY
      : openRecovery;
  const messageByReason: Record<AttachUnavailableReason, string> = {
    handshake_missing: `Rivet is not open for ${projectPath}. Start it with \`rivet open --project ${projectPath}\`.`,
    handshake_invalid: `Rivet's server registration for ${projectPath} is invalid. Restart it with \`rivet open --project ${projectPath}\`.`,
    process_not_running: `The previous Rivet server for ${projectPath} exited. Restart it with \`rivet open --project ${projectPath}\`.`,
    health_check_failed:
      'The Rivet server process is running but is not healthy yet. Retry this command in a moment; if it persists, inspect .rivet/cli/server.log and restart the owning Rivet process.',
    server_starting:
      'The Rivet server is still starting. Retry this command in a moment.',
  };
  return errorResult(
    command,
    'SERVER_UNAVAILABLE',
    messageByReason[reason],
    { serverUnavailableReason: reason },
    recovery,
  );
};

export const attachOrUnavailable = async (
  command: string,
  projectPath: string,
): Promise<AttachedServer | CliCommandResult> => {
  const availability = await inspectServerAvailability(projectPath);
  if (availability.status === 'attached') {
    return availability.server;
  }
  return serverUnavailableResult({
    command,
    projectPath,
    reason: availability.reason,
  });
};

export const isAttached = (
  value: AttachedServer | CliCommandResult,
): value is AttachedServer => 'baseUrl' in value;

const SERVER_ERROR_CODES = new Set<CliErrorCode>([
  'SESSION_NOT_FOUND',
  'WORK_ITEM_NOT_FOUND',
]);

export const serverErrorResult = (
  command: string,
  status: number,
  body: unknown,
): CliCommandResult => {
  const message =
    typeof (body as { error?: unknown })?.error === 'string'
      ? (body as { error: string }).error
      : `Server responded with status ${status}`;
  const reason = (body as { reason?: unknown })?.reason;
  const errorCode =
    typeof reason === 'string' && SERVER_ERROR_CODES.has(reason as CliErrorCode)
      ? (reason as CliErrorCode)
      : 'OPERATION_FAILED';
  return errorResult(command, errorCode, message, body);
};

export const transportErrorResult = (
  command: string,
  error: unknown,
): CliCommandResult => {
  if (
    error instanceof PluginContextMismatchError ||
    error instanceof TelemetryPolicyMismatchError
  ) {
    return commandErrorResult(command, error);
  }
  return errorResult(
    command,
    'SERVER_UNAVAILABLE',
    `Could not reach the Rivet server: ${errorMessage(error)}`,
    { serverUnavailableReason: 'transport_failed' },
    {
      isRecoverable: true,
      nextAction: { action: 'retry', delayMs: RETRY_ACTION_DELAY_MS },
    },
  );
};
